const body = $json.body || $json;
let channel = 'unknown';
if ($('Website Chat Webhook').isExecuted) channel = 'website_chat';
if ($('Contact Form Webhook').isExecuted) channel = 'contact_form';
if ($('WhatsApp Webhook').isExecuted) channel = 'whatsapp';
if ($('Messenger Webhook').isExecuted) channel = 'messenger';
if ($('Voice Receptionist Webhook').isExecuted) channel = 'voice';

const message = (body.message || body.text || body.transcript || body.query || '').toString().trim();
const name = (body.name || body.senderName || body.callerName || '').toString().trim();
const phone = (body.phone || body.from || body.callerNumber || '').toString().trim();
const email = (body.email || '').toString().trim();
const conversationId = body.conversationId || body.conversation_id || (channel + '-' + (phone || email || Date.now()));
const channelId = body.channelId || body.channel_id || body.senderId || '';

const missingFields = [];
if (!message) missingFields.push('message');
if (!phone && !email) missingFields.push('phone_or_email');

return { json: {
  channel, conversation_id: conversationId, channel_id: channelId,
  raw_message: message, contact_name: name, contact_phone: phone, contact_email: email,
  received_at: new Date().toISOString(),
  is_valid: missingFields.length === 0, missing_fields: missingFields,
  source_payload: body
}};

const intake = $('Normalize + Validate Input').item.json;
function clamp(n, lo, hi) { n = Number(n); if (isNaN(n)) return lo; return Math.max(lo, Math.min(hi, n)); }

let parsed = {};
let parseOk = true;
try {
  const rawText = ($json.candidates && $json.candidates[0] && $json.candidates[0].content &&
    $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] &&
    $json.candidates[0].content.parts[0].text) || '{}';
  const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseOk = false;
  parsed = {};
}

return { json: {
  channel: intake.channel, conversation_id: intake.conversation_id, channel_id: intake.channel_id,
  contact_name: intake.contact_name, contact_phone: intake.contact_phone, contact_email: intake.contact_email,
  raw_message: intake.raw_message, received_at: intake.received_at,
  intent: parsed.intent || 'general', property_type: parsed.property_type || '', suburb: parsed.suburb || '',
  budget: parsed.budget || '', bedrooms: parsed.bedrooms || '', bathrooms: parsed.bathrooms || '',
  timeline: parsed.timeline || '', finance_approved: parsed.finance_approved || 'unknown',
  sentiment: parsed.sentiment || 'neutral', urgency: parsed.urgency || 'low',
  spam_probability: clamp(parsed.spam_probability != null ? parsed.spam_probability : 0, 0, 1),
  ai_confidence: clamp(parsed.confidence != null ? parsed.confidence : 0.5, 0, 1),
  lead_score: parseOk ? clamp(parsed.lead_score != null ? parsed.lead_score : 0, 0, 100) : 0,
  lead_tier: parseOk ? (parsed.lead_tier || 'cold') : 'cold',
  next_action: parsed.next_action || 'manual_review', ai_reasoning: parsed.reasoning || '',
  ai_reply: parsed.ai_reply || 'Thanks for reaching out - one of our agents will be in touch shortly.',
  ai_parse_ok: parseOk
}};

const lead = $('Spam Filter Gate').first().json;
const emailMatches = $('Search CRM by Email').all().map(i => i.json).filter(r => r && r.email);
const phoneMatches = $('Search CRM by Phone').all().map(i => i.json).filter(r => r && r.phone);

let existing = null;
if (emailMatches.length) existing = emailMatches[0];
else if (phoneMatches.length) existing = phoneMatches[0];
else {
  const nameLower = (lead.contact_name || '').toLowerCase();
  const combined = [...emailMatches, ...phoneMatches];
  existing = combined.find(r => (r.name || '').toLowerCase() === nameLower && r.phone === lead.contact_phone) || null;
}
const isDuplicate = !!existing;
const leadId = isDuplicate ? existing.lead_id : ('lead_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));

// --- Agent assignment rules ---
const rules = [
  { match: l => l.property_type && l.property_type.toLowerCase().includes('luxury'), agent: 'Agent - Luxury Specialist' },
  { match: l => l.intent === 'tenant', agent: 'Agent - Rentals' },
  { match: l => l.suburb && ['bondi', 'manly', 'toorak'].includes(l.suburb.toLowerCase()), agent: 'Agent - Premium Suburbs' }
];
let assignedAgent = null;
for (const r of rules) { if (r.match(lead)) { assignedAgent = r.agent; break; } }
if (!assignedAgent) {
  const staticData = $getWorkflowStaticData('global');
  const pool = ['Agent A', 'Agent B', 'Agent C'];
  staticData.rrIndex = ((staticData.rrIndex || 0) + 1) % pool.length;
  assignedAgent = pool[staticData.rrIndex];
}

const nowIso = new Date().toISOString();
return [{ json: {
  lead_id: leadId, conversation_id: lead.conversation_id, channel_id: lead.channel_id,
  created_at: isDuplicate ? (existing.created_at || nowIso) : nowIso, updated_at: nowIso,
  last_contact: nowIso, assigned_agent: isDuplicate ? (existing.assigned_agent || assignedAgent) : assignedAgent,
  source: lead.channel, campaign: lead.source_payload && lead.source_payload.campaign ? lead.source_payload.campaign : '',
  status: isDuplicate ? (existing.status || 'active') : 'new', lead_owner: isDuplicate ? existing.assigned_agent : assignedAgent,
  ai_confidence: lead.ai_confidence, sentiment: lead.sentiment, priority: lead.urgency,
  property_type: lead.property_type, bedrooms: lead.bedrooms, bathrooms: lead.bathrooms,
  finance_status: lead.finance_approved, notes: lead.ai_reasoning,
  audit_history: isDuplicate ? ((existing.audit_history || '') + ' | updated ' + nowIso) : ('created ' + nowIso),
  name: lead.contact_name, phone: lead.contact_phone, email: lead.contact_email,
  intent: lead.intent, suburb: lead.suburb, budget: lead.budget, timeline: lead.timeline,
  lead_score: lead.lead_score, lead_tier: lead.lead_tier, next_action: lead.next_action,
  ai_reply: lead.ai_reply, is_duplicate: isDuplicate, follow_up_stage: isDuplicate ? (existing.follow_up_stage || 0) : 0
}}];

