const lead = $('Filter: Needs Booking?').first().json;
const busy = $input.all().map(i => i.json).filter(e => e.start && e.start.dateTime).map(e => ({
  start: new Date(e.start.dateTime), end: new Date(e.end.dateTime)
}));

const businessStartHour = 9, businessEndHour = 17, slotMinutes = 45, travelBufferMinutes = 30;
function overlaps(s, e) { return busy.some(b => s < b.end && e > b.start); }

let day = new Date();
day.setHours(0, 0, 0, 0);
day.setDate(day.getDate() + 1);

const slots = [];
for (let dayOffset = 0; dayOffset < 10 && slots.length < 3; dayOffset++) {
  const d = new Date(day);
  d.setDate(d.getDate() + dayOffset);
  if (d.getDay() === 0) continue; // skip Sunday
  for (let hour = businessStartHour; hour < businessEndHour && slots.length < 3; hour++) {
    for (let min = 0; min < 60 && slots.length < 3; min += 60) {
      const s = new Date(d); s.setHours(hour, min, 0, 0);
      const e = new Date(s.getTime() + (slotMinutes + travelBufferMinutes) * 60000);
      if (!overlaps(s, e)) slots.push({ start: s.toISOString(), end: new Date(s.getTime() + slotMinutes * 60000).toISOString() });
    }
  }
}
return [{ json: { lead_id: lead.lead_id, name: lead.name, email: lead.email, phone: lead.phone, suburb: lead.suburb, slots } }];

