const body = $json.body || $json;
const validSelection = ['1', '2', '3'].includes(String(body.selection));
return { json: {
  lead_id: body.lead_id || '', selection: body.selection, is_valid: validSelection,
  slot_start: body.slot_start || '', slot_end: body.slot_end || '',
  name: body.name || '', email: body.email || ''
}};

const body = $('Missed Call Webhook').item.json.body || {};
return { json: {
  lead_id: 'call_' + Date.now(), phone: body.CallerNumber || body.from || '',
  status: 'missed_call_recovery', recovery_sms_sent: true, missed_call_at: new Date().toISOString()
}};

const STAGE_DAYS = [1, 3, 7, 14];
const STOP_STATUSES = ['booked', 'replied', 'opted_out', 'cancelled'];
const now = Date.now();
const due = [];

for (const item of $input.all()) {
  const lead = item.json;
  if (STOP_STATUSES.includes(lead.status)) continue;
  const stage = Number(lead.follow_up_stage || 0);
  if (stage >= STAGE_DAYS.length) continue;
  const lastContact = lead.last_contact ? new Date(lead.last_contact).getTime() : 0;
  const daysSince = (now - lastContact) / (1000 * 60 * 60 * 24);
  if (daysSince >= STAGE_DAYS[stage]) {
    due.push({ ...lead, next_stage: stage + 1, days_since_contact: Math.floor(daysSince) });
  }
}
return due.map(d => ({ json: d }));

const body = $json.body || $json;
return { json: {
  address: body.address || '', suburb: body.suburb || '', property_type: body.property_type || '',
  bedrooms: body.bedrooms || '', bathrooms: body.bathrooms || '', car_spaces: body.car_spaces || '',
  key_features: body.key_features || '', price_guide: body.price_guide || '', agent_name: body.agent_name || ''
}};

const details = $('Prepare Listing Prompt').item.json;
let parsed = {};
try {
  const rawText = ($json.candidates && $json.candidates[0] && $json.candidates[0].content &&
    $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] &&
    $json.candidates[0].content.parts[0].text) || '{}';
  parsed = JSON.parse(rawText.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) { parsed = {}; }

return { json: { address: details.address, suburb: details.suburb, agent_name: details.agent_name,
  listing_title: parsed.listing_title || '', seo_title: parsed.seo_title || '',
  meta_description: parsed.meta_description || '', property_description: parsed.property_description || '',
  facebook_post: parsed.facebook_post || '', instagram_caption: parsed.instagram_caption || '',
  linkedin_post: parsed.linkedin_post || '', google_business_post: parsed.google_business_post || '',
  email_campaign_copy: parsed.email_campaign_copy || '', brochure_copy: parsed.brochure_copy || '',
  short_description: parsed.short_description || '', luxury_version: parsed.luxury_version || '',
  investor_version: parsed.investor_version || '', first_home_buyer_version: parsed.first_home_buyer_version || '',
  generated_at: new Date().toISOString() }};

return { json: {
  event_type: $json.lead_tier ? 'lead_qualified' : ($json.listing_title ? 'listing_generated' : 'event'),
  lead_tier: $json.lead_tier || '', channel: $json.channel || $json.source || '',
  logged_at: new Date().toISOString()
}};

const rows = $input.all().map(i => i.json);
const totalLeads = rows.filter(r => r.event_type === 'lead_qualified').length;
const hot = rows.filter(r => r.lead_tier === 'hot').length;
const warm = rows.filter(r => r.lead_tier === 'warm').length;
const cold = rows.filter(r => r.lead_tier === 'cold').length;
const listingsGenerated = rows.filter(r => r.event_type === 'listing_generated').length;
const missedCalls = rows.filter(r => r.event_type === 'missed_call_recovery').length;

return [{ json: {
  summary_date: new Date().toISOString().slice(0, 10),
  total_leads: totalLeads, hot_leads: hot, warm_leads: warm, cold_leads: cold,
  conversion_rate: totalLeads ? Math.round((hot / totalLeads) * 100) : 0,
  listings_generated: listingsGenerated, missed_calls_logged: missedCalls
}}];

const exec = $json.execution || {};
const wf = $json.workflow || {};
return { json: {
  error_message: exec.error ? exec.error.message : 'Unknown error',
  failed_node: exec.lastNodeExecuted || 'unknown',
  failed_workflow: wf.name || 'RealEstate_AI_OS',
  occurred_at: new Date().toISOString()
}};
